import{_ as a,o as i,c as t,a2 as e}from"./chunks/framework.D66Xq0Kv.js";const c=JSON.parse('{"title":"03-2 Fuzz、Invariant 与调试：测试不只是写几个例子","description":"","frontmatter":{},"headers":[],"relativePath":"03-foundry/advanced-test.md","filePath":"03-foundry/advanced-test.md","lastUpdated":1791601077000}'),n={name:"03-foundry/advanced-test.md"};function l(d,s,h,r,p,o){return i(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="_03-2-fuzz、invariant-与调试-测试不只是写几个例子" tabindex="-1">03-2 Fuzz、Invariant 与调试：测试不只是写几个例子 <a class="header-anchor" href="#_03-2-fuzz、invariant-与调试-测试不只是写几个例子" aria-label="Permalink to &quot;03-2 Fuzz、Invariant 与调试：测试不只是写几个例子&quot;">​</a></h1><blockquote><p><strong>本课目标</strong>：理解单元测试、Fuzz、Invariant 的差别，运行一次本仓库的 Fuzz 测试，并掌握失败时的排查顺序。</p><p>初学时先学会<strong>说清楚测试在证明什么</strong>，不要因为看到术语就急着装十个工具。</p></blockquote><h2 id="第一层-普通单元测试" tabindex="-1">第一层：普通单元测试 <a class="header-anchor" href="#第一层-普通单元测试" aria-label="Permalink to &quot;第一层：普通单元测试&quot;">​</a></h2><p>上一课写过：</p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">counter.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">increase</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">require</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(counter.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">count</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;wrong increase&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>这只证明一种输入：<strong>增加 3 是正确的</strong>。但如果参数是 0、1、最大整数、很大数字呢？</p><p>这就进入第二层。</p><h2 id="第二层-fuzz-——-自动尝试大量输入" tabindex="-1">第二层：Fuzz —— 自动尝试大量输入 <a class="header-anchor" href="#第二层-fuzz-——-自动尝试大量输入" aria-label="Permalink to &quot;第二层：Fuzz —— 自动尝试大量输入&quot;">​</a></h2><p>本仓库 <code>test/Counter.t.sol</code> 里有：</p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">function</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> testFuzz_Increase</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">uint256</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> amount</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    counter.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">increase</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(amount);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    require</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(counter.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">count</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> amount, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;count mismatch&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>你不需要自己列出 1、2、3、100、1000……Foundry 会生成多组 <code>uint256</code> 输入，并检查同一性质：<strong>一个新计数器增加 amount 后，count 必须等于 amount</strong>。</p><p>运行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/foundry</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">forge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --match-test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> testFuzz_Increase</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -vv</span></span></code></pre></div><p>预期：用例通过，输出里可能包含 runs 等 Fuzz 统计。本仓库配置 <code>fuzz = { runs = 128 }</code>；实际运行次数与版本、过滤设置有关，以终端结果为准。</p><h3 id="fuzz-能证明所有输入都安全吗" tabindex="-1">Fuzz 能证明所有输入都安全吗？ <a class="header-anchor" href="#fuzz-能证明所有输入都安全吗" aria-label="Permalink to &quot;Fuzz 能证明所有输入都安全吗？&quot;">​</a></h3><p>不能。它抽样检查一些输入和路径，不能自动保证覆盖所有可能情况。对“输入范围、前置状态、调用身份”没有设计的 Fuzz 测试，也可能漏掉核心风险。</p><p>例如如果测试只写“金额小于 10 时会成功”，却从未验证退款后第二次领取会失败，那么再多次随机测试也不能证明不会重复付款。</p><h2 id="第三层-invariant-——-无论怎样操作都必须成立的规则" tabindex="-1">第三层：Invariant —— 无论怎样操作都必须成立的规则 <a class="header-anchor" href="#第三层-invariant-——-无论怎样操作都必须成立的规则" aria-label="Permalink to &quot;第三层：Invariant —— 无论怎样操作都必须成立的规则&quot;">​</a></h2><p>假设 Escrow 合约允许：买家付款 → 卖家交付 → 买家放款，或者到期退款。</p><p>可能的不变量包括：</p><ol><li>一笔托管订单<strong>不能既退款又放款</strong>。</li><li>进入 Released 后<strong>不能再回到 Funded</strong>。</li><li>进入 Refunded 后<strong>不能再放款</strong>。</li><li>非授权地址不能改变资金归属。</li><li>合约状态和资金去向必须能解释，不能无缘无故“多付一笔”。</li></ol><p>区别在于：Fuzz 常常针对某个函数的大量入参；<strong>状态机不变量</strong>更关注一系列操作组合后，规则是否仍成立。例如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>创建订单 → 标记交付 → 退款 → 再次放款</span></span>
<span class="line"><span>                           ↑</span></span>
<span class="line"><span>                        必须阻止</span></span></code></pre></div><p>工程中通常会编写 handler 控制动作、身份和前置条件，避免把“设计上就应该失败”的调用误当作安全漏洞。<strong>本仓库 v0.1 有 Fuzz 用例，但完整 Invariant Handler 仍属后续工作，不应当成已实现功能。</strong></p><h2 id="第四层-边界值-比随机输入还重要" tabindex="-1">第四层：边界值，比随机输入还重要 <a class="header-anchor" href="#第四层-边界值-比随机输入还重要" aria-label="Permalink to &quot;第四层：边界值，比随机输入还重要&quot;">​</a></h2><p>拿一个截止时间 <code>deadline</code> 举例：</p><table tabindex="0"><thead><tr><th>输入时间</th><th>是否允许到期退款</th></tr></thead><tbody><tr><td><code>deadline - 1</code></td><td>不应该允许</td></tr><tr><td><code>deadline</code></td><td>应允许</td></tr><tr><td><code>deadline + 1</code></td><td>应允许</td></tr></tbody></table><p>这叫边界测试。“差一秒”往往比测试一千个随机的普通时间更能找到错误。</p><p>但真实公链的时间戳存在协议和区块生产相关的限制，不能把它当成精确的现实世界定时器。</p><h2 id="看懂-foundry-的本地测试作弊码" tabindex="-1">看懂 Foundry 的本地测试作弊码 <a class="header-anchor" href="#看懂-foundry-的本地测试作弊码" aria-label="Permalink to &quot;看懂 Foundry 的本地测试作弊码&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Cheatcode</th><th>白话含义</th><th>用在哪里</th></tr></thead><tbody><tr><td><code>vm.prank(addr)</code></td><td>让下一次调用模拟为 addr</td><td>测试陌生人越权</td></tr><tr><td><code>vm.expectRevert(...)</code></td><td>预期下一次调用失败</td><td>测试权限 / 状态错误</td></tr><tr><td><code>vm.warp(timestamp)</code></td><td>在本地测试环境改变区块时间</td><td>测试到期边界</td></tr><tr><td><code>vm.deal(addr, amount)</code></td><td>在本地测试给地址设置余额</td><td>测试付款</td></tr><tr><td><code>vm.expectEmit(...)</code></td><td>预期发出指定事件</td><td>验证审计日志</td></tr></tbody></table><p>这些能力属于<strong>本地模拟测试环境</strong>，不是上线后某个用户真的可以修改主网时间或他人的余额。</p><h2 id="出现-fail-怎么排查-按顺序来" tabindex="-1">出现 FAIL 怎么排查？按顺序来 <a class="header-anchor" href="#出现-fail-怎么排查-按顺序来" aria-label="Permalink to &quot;出现 FAIL 怎么排查？按顺序来&quot;">​</a></h2><ol><li><strong>看名字</strong>：哪条测试失败？是正常场景还是反向场景？</li><li><strong>看输入</strong>：尤其 Fuzz 输出中的失败参数，是否进入了你没想到的边界？</li><li><strong>看调用者</strong>：当前 <code>msg.sender</code> 是谁？是否被 prank 修改？</li><li><strong>看状态</strong>：执行前是 Funded、Delivered，还是已退款？</li><li><strong>看时间与余额</strong>：是否刚好在截止点？</li><li><strong>看错误</strong>：期望的 revert 与实际错误是否一致？</li><li><strong>打开调用轨迹</strong>：</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">forge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --match-test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> testRefundAfterDeadline</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -vvvv</span></span></code></pre></div><p>如果这个名字在你的代码版本中不存在，先用 <code>forge test --list</code> 查看当前测试名，再替换成实际名称。</p><h2 id="做一份自己的测试清单" tabindex="-1">做一份自己的测试清单 <a class="header-anchor" href="#做一份自己的测试清单" aria-label="Permalink to &quot;做一份自己的测试清单&quot;">​</a></h2><p>以 Escrow 为例，不需要马上写代码，先在笔记里列出：</p><ul><li>买家付款后余额应该怎样？</li><li>卖家未交付，买家能否放款？</li><li>陌生人能否标记交付？</li><li>截止时间前一秒能否退款？</li><li>截止时间恰好到达能否退款？</li><li>已经放款，还能再退款吗？</li></ul><p>每一个问题都能变成一条自动化测试。</p><h2 id="本课验收" tabindex="-1">本课验收 <a class="header-anchor" href="#本课验收" aria-label="Permalink to &quot;本课验收&quot;">​</a></h2><ul><li>运行了 <code>testFuzz_Increase</code>。</li><li>能说出 Fuzz 测的是哪一个<strong>性质</strong>。</li><li>能举出至少两个“重复结算不允许”的状态不变量。</li><li>明白“Fuzz 通过”和“专业安全审计通过”完全是两回事。</li></ul><p>下一课：<a href="/04-security/">重入攻击到底如何发生，为什么要先改状态再转账</a>。</p>`,43)])])}const u=a(n,[["render",l]]);export{c as __pageData,u as default};
